<?php
require_once __DIR__ . '/includes/bootstrap.php';
$pageTitle='Lapor Lingkungan';
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $type=trim($_POST['type']??''); $location=trim($_POST['location']??''); $description=trim($_POST['description']??'');
 if(mb_strlen($name)<2 || mb_strlen($name)>100) $errors[]='Nama harus berisi 2–100 karakter.';
 if($email!=='' && !filter_var($email,FILTER_VALIDATE_EMAIL)) $errors[]='Format email tidak valid.';
 if(!in_array($type,['Sampah menumpuk','Pencemaran air','Kerusakan ruang hijau','Pemborosan sumber daya','Lainnya'],true)) $errors[]='Pilih jenis laporan yang tersedia.';
 if(mb_strlen($location)<4 || mb_strlen($location)>180) $errors[]='Lokasi harus berisi 4–180 karakter.';
 if(mb_strlen($description)<15 || mb_strlen($description)>2000) $errors[]='Deskripsi harus berisi 15–2.000 karakter.';
 if(!$errors){$stmt=$pdo->prepare("INSERT INTO reports(name,email,type,location,description) VALUES(?,?,?,?,?)");$stmt->execute([$name,$email?:null,$type,$location,$description]);flash('success','Terima kasih. Laporanmu telah tercatat dan akan ditinjau oleh pengelola.');header('Location: lapor.php');exit;}
}
require __DIR__ . '/includes/header.php';
